entries[283399] = { ["name"] = "Üb3r-Modul: Bombenbots mit kurzer Lunte", ["text"] = "Wirken in 3.5 sek.\nTools: Üb3r-Schrauber\nReagenzien:\nMoneliterz (5), Sturmsilbererz (2), Isoliertes Kabel (15), Chemische Sprengkapsel (10)\nErschafft ein Üb3r-Modul: Bummbots mit kurzer Lunte.\nQuest:\nDer Üb3r-Schrauber\nZone:\nZuldazar\n\nQuest:\nDer Üb3r-Schrauber\nZone:\nTiragardesund\n\nÜb3r-Modul: Bummbots mit kurzer Lunte\n(0)\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Garantiert, dass Eure Üb3r-Erfindungen Bombenbots mit kurzer Lunte sind.\nBenötigt Ingenieurskunst von Kul Tiras\n(50)" }
entries[283401] = { ["name"] = "Üb3r-Modul: Üb3rwächt3r Mk. X8.0", ["text"] = "Wirken in 3.5 sek.\nTools: Üb3r-Schrauber\nReagenzien:\nMoneliterz (10), Sturmsilbererz (5), Isoliertes Kabel (10), Chemische Sprengkapsel (2)\nErschafft ein Üb3r-Modul: Üb3rwächt3r Mk. X8.0.\nQuest:\nDer Üb3r-Schrauber\nZone:\nZuldazar\n\nQuest:\nDer Üb3r-Schrauber\nZone:\nTiragardesund\n\n(0)\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Garantiert, dass Eure Üb3r-Erfindungen Üb3rwächt3r Mk. X8.0 sind.\nBenötigt Ingenieurskunst von Kul Tiras\n(50)" }
entries[283403] = { ["name"] = "Üb3r-Modul: Üb3r-aufgemotzte Zielattrappe", ["text"] = "Wirken in 3.5 sek.\nTools: Üb3r-Schrauber\nReagenzien:\nMoneliterz (5), Sturmsilbererz (2), Isoliertes Kabel (5)\nErschafft ein Üb3r-Modul: Üb3r-aufgemotzte Zielattrappe.\nQuest:\nDer Üb3r-Schrauber\nZone:\nZuldazar\n\nQuest:\nDer Üb3r-Schrauber\nZone:\nTiragardesund\n\n(0)\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Garantiert, dass Eure Üb3r-Erfindungen Üb3r-aufgemotzte Zielattrappen sind.\nBenötigt Ingenieurskunst von Kul Tiras\n(50)" }
