entries[283421] = { ["name"] = "Maximaler Schub", ["text"] = "Kanalisiert\nBei Erreichen von 100 Energie stürmt Gnominator G-800 in die Richtung eines zufälligen Gegners, verursacht auf seinem Weg 10910022 körperlichen Schaden und stößt alle getroffenen Gegner zurück.\n\nWenn der Bot mit der Wand der Arena kollidiert, wird er für 5 Sek. betäubt und mehrere Instanzen von ' K.4.M.P.F.-Mine ' werden auf Positionen in der Nähe geschleudert." }
entries[283422] = { ["name"] = "Maximaler Schub", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nBei Erreichen von 100 Energie stürmt Gnominator G-800 in die Richtung eines zufälligen Gegners, verursacht auf seinem Weg 10910022 körperlichen Schaden und stößt alle getroffenen Gegner zurück.\n\nWenn der Bot mit der Wand der Arena kollidiert, wird er für 5 Sek. betäubt und mehrere Instanzen von ' K.4.M.P.F.-Mine ' werden auf Positionen in der Nähe geschleudert." }
entries[283423] = { ["name"] = "Zuschlagen", ["text"] = "Nahkampfreichweite\nSofort 15 sek. Abklingzeit\nSchlägt auf das Ziel ein, unterbricht das Wirken von Zaubern und verhindert 4 Sek. lang, dass diese Art Zauber gewirkt werden kann." }
entries[283424] = { ["name"] = "Hinrichten", ["text"] = "20 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nVersucht, einen Gegner zu erledigen und verursacht dabei 522799 körperlichen Schaden." }
entries[283426] = { ["name"] = "Überwältigen", ["text"] = "Nahkampfreichweite\nSofort 9 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nÜberwältigt den Gegner und fügt ihm 214348 körperlichen Schaden zu. Der Angriff kann nicht geblockt oder pariert und ihm kann nicht ausgewichen werden.\n\nErhöht den Schaden Eures nächsten Einsatzes von 'Tödlicher Stoß' um 20%. Bis zu 2-mal stapelbar." }
