entries[283429] = { ["name"] = "Bevorstehender Sieg", ["text"] = "10 Energie Nahkampfreichweite\nSofort 30 sek. Abklingzeit\nGreift das Ziel sofort an, verursacht 2 Schaden und heilt Euch um 30% Eurer maximalen Gesundheit.\n\nNach dem Töten eines Gegners, der Erfahrung oder Ehre gewährt, wird die Abklingzeit von 'Bevorstehender Sieg' abgeschlossen." }
