entries[283431] = { ["name"] = "Fluch der Verwundbarkeit", ["text"] = "Sofort\nVerflucht alle Gegner, sodass erlittener Magieschaden Ziele mit einer Verwundbarkeitsaura belegt, die den durch diese Magieart erlittenen Schaden um 100% erhöht. Wenn das Ziel Schaden einer anderen Magieart erleidet, ändert sich die Verwundbarkeit." }
entries[283433] = { ["name"] = "Avatar", ["text"] = "Sofort 1.5 min Abklingzeit\nIhr verwandelt Euch für 20 Sek. in einen Koloss, wodurch Ihr 20% mehr Schaden verursacht und Euch von allen bewegungseinschränkenden und Bewegungsunfähigkeitseffekten befreit.\n\nErzeugt 2 Wut." }
