entries[283507] = { ["name"] = "Unstete Ladung", ["text"] = "Wirken in 2 sek.\nBelegt Spielercharaktere mit einer unsteten Ladung, die 8 Sek. lang alle 1 Sek. 1636 Naturschaden verursacht. Nach Ablauf des Effekts stoßen Spielercharaktere diese aus und fügen nahen Spielercharakteren 13085 Naturschaden zu. Ausgestoßene Ladungen fügen Gegnern innerhalb von 6 Metern regelmäßig 13085 Naturschaden zu." }
