entries[283667] = { ["name"] = "Blutung", ["text"] = "25 Energie / 1 zu 5 Combopunkte Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der das Fleisch des Ziels aufreißt und regelmäßigen Blutungsschaden verursacht. Hält pro Combopunkt länger an.\n\n1 Punkt: (57495 * 2) im Verlauf von 8 Sek.\n2 Punkte: (57495 * 3) im Verlauf von 12 Sek.\n3 Punkte: (57495 * 4) im Verlauf von 16 Sek.\n4 Punkte: (57495 * 5) im Verlauf von 20 Sek.\n5 Punkte: (57495 * 6) im Verlauf von 24 Sek." }
entries[283668] = { ["name"] = "Blutroter Sturm", ["text"] = "35 Energie / 5 Combopunkte\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der alle Gegner innerhalb von 10 Metern aufschlitzt. Verursacht sofort Schaden und lässt Opfer bluten, wodurch sie zusätzlichen Schaden erleiden. Hält pro Combopunkt länger an.\n\n1 Punkt: 4 plus 10 im Verlauf von 4 Sek.\n2 Punkte: 6 plus 15 im Verlauf von 6 Sek.\n3 Punkte: 8 plus 20 im Verlauf von 8 Sek.\n4 Punkte: 10 plus 25 im Verlauf von 10 Sek.\n5 Punkte: 12 plus 30 im Verlauf von 12 Sek." }
