entries[283914] = { ["name"] = "Instabiler temporaler Zeitverschieber", ["text"] = "Wirken in 2 sek.\nReagenzien:\nMoneliterz (12), Sturmsilbererz (8), Isoliertes Kabel (20)\nStellt einen instabilen temporalen Zeitverschieber her.\nBerufsausbilder:\nIngenieurskunst von Battle for Azeroth (85)\nKosten:\n5\n25\n\nBenötigt Ingenieurskunst von Kul Tiras\n(85)\n\"Dieses Gerät kann zwar die Toten ins Leben zurückrufen, versetzt aber unter Umständen auch die Lebenden an die Schwelle des Todes.\"" }
entries[283915] = { ["name"] = "Instabiler temporaler Zeitverschieber", ["text"] = "Wirken in 2 sek.\nReagenzien:\nMoneliterz (10), Sturmsilbererz (7), Isoliertes Kabel (18)\nVerringert die erforderlichen Materialien zur Herstellung eines instabilen temporalen Zeitverschiebers.\nVerkäufer:\nNatal'hakata\nZone:\nZuldazar\nZandalariimperium - Ehrfürchtig\nKosten:\n1900\n\nBenötigt Ingenieurskunst von Kul Tiras\n(85)\n\"Dieses Gerät kann zwar die Toten ins Leben zurückrufen, versetzt aber unter Umständen auch die Lebenden an die Schwelle des Todes.\"" }
entries[283916] = { ["name"] = "Instabiler temporaler Zeitverschieber", ["text"] = "Wirken in 2 sek.\nReagenzien:\nMoneliterz (8), Sturmsilbererz (6), Isoliertes Kabel (15)\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines instabilen temporalen Zeitverschiebers.\nBeute von:\nHochtüftler Mekkadrill\nZone:\nSchlacht von Dazar'alor\n\nBenötigt Ingenieurskunst von Kul Tiras\n(85)\n\"Dieses Gerät kann zwar die Toten ins Leben zurückrufen, versetzt aber unter Umständen auch die Lebenden an die Schwelle des Todes.\"" }
